from pathlib import Path
import json,csv,statistics as st,os
R=Path(__file__).resolve().parent
os.environ['MPLCONFIGDIR']=str(R/'.mplconfig')
for k in ('OMP_NUM_THREADS','OPENBLAS_NUM_THREADS','MKL_NUM_THREADS','NUMEXPR_NUM_THREADS','VECLIB_MAXIMUM_THREADS'):os.environ[k]='1'
def read(n):return list(csv.DictReader((R/'tables'/n).open()))
s=json.loads((R/'analysis_summary.json').read_text());a=s['all'];cases=read('cases.csv');sel=read('selection.csv');quality=read('quality.csv');components=read('components.csv');setup=read('setup.csv')
def f(x):return f'{float(x):.3f}'
def component(ds,m,c):return float(next(x['mean_ms'] for x in components if x['dataset']==ds and x['method']==m and x['component']==c))
lines=['# Client identity robustness of reviewed compact T0 deletion','',f"Completed all 30 frozen cases (six distinct dataset/client requests × five seeds) and 270 timed requests. The unchanged compact method matches canonical fresh T0 indexed models and declared compact state throughout. Across all requests, Fresh/Fast is {a['fresh_fast_total_ratio']:.2f}× and Direct/Fast is {a['direct_fast_total_ratio']:.2f}×. All 30 case means favor fast; no losses or ties were discarded. This supports the speedup across these selected original-partition endpoints, not arbitrary client populations or a general 10× guarantee.",'','## Selection and actual diversity','','Only original metadata determined selection. Empty-group requests were filtered before selection; none were excluded. Smallest, nearest median, minimum group-0 fraction select client 0 in each dataset. Largest, maximum group-0 fraction, minimum smaller surviving group select the last client. Six roles therefore collapse into two clients per dataset; no replacements were made. All ties use the smallest persistent original run ID, which here equals the source client ID. Median uses doubled integer distance over valid clients. Exact fractions and every original client metadata record are in SELECTION.json.','','| Dataset / client | Removed n | Group 0 / 1 | Group-0 fraction | Remaining group 0 / 1 |','|---|---:|---:|---:|---:|']
for r in sel:lines.append(f"| {r['dataset']} / {r['client']} | {r['size']} | {r['group0']} / {r['group1']} | {r['group0_fraction']} | {r['remaining0']} / {r['remaining1']} |")
lines+=['','The metadata show 99 equal-sized clients plus one remainder client for Adult and Credit, and 19 plus one for Bank. Bank differs little in either size or composition (2259 versus 2290 rows, group-0 share about 39.80% versus 40%). Credit changes group-0 share from about 17.73% to 34.59%; Adult changes from 32.33% to 38.74%. These requests cover the prespecified extremes but do not create six independent client types. Clients, roles and seeds are correlated; repetitions are technical repeats.','','## Matched request latency','','Means below are milliseconds over five seeds and three repetitions per seed. Ratios are ratios of summed request times, not means of paired ratios. The request includes preparation, complete method call, exact model projection/serialization and local file write without fsync. All methods start resident and emit the same bytes for a given case.','','| Dataset / departed client | Fresh ms | Direct ms | Compact ms | Fresh/Compact | Direct/Compact | Paired Fresh/Compact range |','|---|---:|---:|---:|---:|---:|---:|']
for r in s['clients']:lines.append(f"| {r['group']} | {r['fresh_request_e2e_seconds_mean_ms']:.3f} | {r['direct_request_e2e_seconds_mean_ms']:.3f} | {r['fast_request_e2e_seconds_mean_ms']:.3f} | {r['fresh_fast_total_ratio']:.2f}× | {r['direct_fast_total_ratio']:.2f}× | {r['fresh_fast_paired_min']:.2f}–{r['fresh_fast_paired_max']:.2f} |")
lines+=['',f"Total request seconds: Fresh {a['fresh_request_e2e_seconds_total_ms']/1000:.6f}, Direct {a['direct_request_e2e_seconds_total_ms']/1000:.6f}, Compact {a['fast_request_e2e_seconds_total_ms']/1000:.6f}. Fresh/Direct is {a['fresh_direct_total_ratio']:.2f}×. Algorithm-only Fresh/Compact is {a['fresh_algorithm_seconds_total_ms']/a['fast_algorithm_seconds_total_ms']:.2f}×. The Fresh/Compact paired-case mean/median/sample SD is {a['fresh_fast_paired_mean']:.2f}/{a['fresh_fast_paired_median']:.2f}/{a['fresh_fast_paired_sd']:.2f}, range {a['fresh_fast_paired_min']:.2f}–{a['fresh_fast_paired_max']:.2f}. Dataset heterogeneity explains why the paired mean differs from the pooled total-time ratio.",'','All 30 mean Fresh/Compact ratios exceed 10; all 30 Direct/Compact ratios exceed 1. These are observations, not a threshold-conditioned selection or guarantee. No failed scientific case, timing retry, dropped observation, tie, or speed loss occurred. Each method occupies each position once in each case.']
for m in ('fresh','direct','fast'):
 vals=[100*float(c[f'{m}_request_cv']) for c in cases];lines.append(f"Within-case {m} request-time CV across three repeats ranges {min(vals):.2f}%–{max(vals):.2f}%.")
lines+=['','tables/summary.csv includes dataset, actual distinct client, overlapping dataset/role, seed, and dataset/seed totals, paired ratio means/medians/SD/ranges and win/loss/tie counts. tables/cases.csv retains every seed/client mean, repeat SD/CV/range, and absolute preparation/algorithm/output costs. tables/raw_timings.csv retains all 270 observations. No IID confidence interval is appropriate for this grid.','','## Workload and component explanation','','All retained slices in this grid supply ten anchors. Both departing identities leave 1,980 anchors across 198 slices on Adult and Credit, and 380 anchors across 38 slices on Bank. Thus changing client identity changes exact group normalization and sampled model but does not reduce the number of surviving anchors within a dataset. The fast path must rebuild exact weights and sample the server again. Composition differences cannot be interpreted as a separate causal latency effect here.','','| Dataset | Fresh local seeding ms | Fresh encoding ms | Direct input materialization ms | Fast metadata ms | Fast table ms | Fast sampler ms | Fast output ms |','|---|---:|---:|---:|---:|---:|---:|---:|']
for ds in ('adult','bank','credit'):
 vals=[component(ds,'fresh','component_phase1_client_seconds'),component(ds,'fresh','component_encoding_seconds'),component(ds,'direct','component_input_materialization_seconds'),component(ds,'fast','component_metadata_seconds'),component(ds,'fast','component_anchor_table_seconds'),component(ds,'fast','component_server_sampler_seconds'),component(ds,'fast','output_seconds')];lines.append('| '+ds+' | '+' | '.join(f'{v:.3f}' for v in vals)+' |')
lines+=['','Fast request preparation is only about 0.0004–0.0006 ms. Its substantial costs are table materialization, server sampling and output. Fresh rebuilds local summaries; Direct reuses them but retains raw-input bookkeeping/materialization and phase-one overhead. Component labels come from the actual public API timers; uninstrumented residuals are not pure scanning estimates. Fresh reports zero in the dedicated input-materialization field while its actual conversion/copy work remains inside encoding and residual costs. Table construction and sampler are separate for fast but combined in fresh/direct server time. All component sums reconcile to the full public-call timer.','','Bank retains far fewer anchors and has fewer feature dimensions than Adult, making compact server work much cheaper while fresh still processes roughly 43,000 retained rows. Adult/Credit retain the same anchor count but differ in feature dimension (103 versus 23) and data geometry. These explain workload differences; this small observation grid does not isolate causal effects of any one factor.','','## Setup, exclusions and concurrency','','One original-population T0 checkpoint and one compact state were constructed per dataset/seed, reused for the two independent requests, and verified unmodified. Each request starts from that original state, not the prior deletion result. No full checkpoint was persisted. In-memory pickle size/cost is reported solely as setup information.','','| Dataset | Mean load/identity ms | Mean original train ms | Mean compaction ms | Canonical / compact pickle MiB |','|---|---:|---:|---:|---:|']
for ds in ('adult','bank','credit'):
 rows=[r for r in setup if r['batch'].startswith(ds)];mean=lambda k:st.mean(float(r[k]) for r in rows);lines.append(f"| {ds} | {mean('load_ms'):.3f} | {mean('initial_training_ms'):.3f} | {mean('compaction_ms'):.3f} | {mean('canonical_pickle_bytes')/2**20:.3f} / {mean('compact_pickle_bytes')/2**20:.3f} |")
logs=[json.loads(x) for x in (R/'runs/diversity-v1/lock.jsonl').read_text().splitlines()];loads=[x['load_average'][0] for x in logs if 'load_average' in x]
lines +=['',f"All 15 parent-held shared-lock batches completed, with total lock wait {s['lock_wait_seconds']:.6f} s and hold {s['lock_held_seconds']:.3f} s. Acquisition/release receipts include top CPU processes and load averages; one-minute load ranges {min(loads):.2f}–{max(loads):.2f}. Numerical workers were serial with OMP/OpenBLAS/MKL/NumExpr/vecLib limits set to one. The lock cannot eliminate unrelated desktop load. Python 3.12.14, NumPy 2.3.5, macOS 27 arm64; actual executable/platform/thread settings appear in each setup receipt.",'','Cold input/checkpoint loading, Python startup, initial training/compaction, initial serialization, pre-request GC, untimed correctness gates, comparisons/receipts, quality scoring and durable next-state persistence are outside request timing. Dataset load/identity, training/compaction, serialization and batch wall times are recorded separately. Process-startup and hypothetical durable-service costs were not separately measured. Gates warm the methods before timing. No network or distributed deployment latency is measured.','','## Exact T0 quality only','','Exact group-average and worst-group costs were scored once per retained population/seed on the represented data. Phi=max(Phi_A,Phi_B), G=Phi_A+Phi_B, verified from exact rational values for all 30 cases. Below are five-seed means; averaging happens after the per-case maximum.','','| Dataset / client | Mean group 0 | Mean group 1 | Mean Phi | Phi seed range |','|---|---:|---:|---:|---:|']
for c in s['clients']:
 ds,cl=c['group'].split('/c');rows=[q for q in quality if q['dataset']==ds and q['client']==cl];phi=[float(q['Phi']) for q in rows];lines.append(f"| {c['group']} | {st.mean(float(q['Phi_A']) for q in rows):.3f} | {st.mean(float(q['Phi_B']) for q in rows):.3f} | {st.mean(phi):.3f} | {min(phi):.3f}–{max(phi):.3f} |")
lines+=['',f"Total quality materialization/scoring costs were {sum(float(q['materialization_ms']) for q in quality)/1000:.3f}/{sum(float(q['scoring_ms']) for q in quality)/1000:.3f} seconds, outside all request ratios. No positive-budget reference was rerun or imported. These values establish neither optimality nor whether unmeasured refinement would be adequate or necessary.",'','## Correctness and claims','','**Previously proved, conditional:** the reviewed whole-client T0 summary invariant gives same-seed indexed equality under fixed preprocessing, original persistent IDs, exact current counts, canonical server replay and trusted unmodified summaries. This study changes no algorithm and supplies additional finite tests; it does not present the tests as a new proof.','','**Tested here:** 30 untimed gates, 60 replay-versus-fresh model and declared-state gate comparisons, 30 returned compact-state gate checks; 270 timed model and declared-state comparisons against fresh gates, and 90 returned compact-state comparisons. Declared state includes counts, every retained summary field/byte, ordered anchors and exact rational weights. Output center bytes, shapes, float.hex values and the single indexed C0 trajectory were independently parsed. T0 has no refinement-statistics rounds. The complete original compact state remained unchanged after both requests in each batch. All 270 output files and case receipt hashes passed.','','**Conditional empirical conclusion:** whole-client speedup survives the selected identity/seed variations on these three original partitions under the stated warm resident-data output contract. Local timing and source/input bindings are essential. A different optimized baseline, architecture, cold-start/persistence boundary, partition or learner budget can change the result.','','**Unresolved or outside scope:** optimality, T0 adequacy relative to unmeasured refinement, arbitrary/adaptive client selection, independent fresh randomness after model-adaptive requests, untrusted/mutated compact state, full internal-cache identity, physical personal-data erasure, and a universal 10× claim. Original datasets/checkpoints and historical states remain; anchors may themselves contain represented records. Upstream fixed-preprocessing/provenance limitations remain those of the accepted inputs. No sensitive material was uploaded or shared.','','## Artifacts and preservation','','PROTOCOL.md and FROZEN_GRID.json were bound before the first gate/timing. SOURCE_VERIFICATION.json binds the exact reviewed candidate; COMPLETED_INPUT_BINDINGS.json verifies relevant completed inputs remain byte-identical. VERIFICATION.json checks saved witnesses; TABLE_VERIFICATION.json separately recomputes every summary field from raw JSON without importing production or report-generation code. All tables, commands and source are local. Frozen candidate SHA256: `6d7b8d993ed9e9fcda896192ee6e6299a434ab7cdc25ab9907fc6b4bc1cf3dde`. MANIFEST.json inventories final deliverables/evidence. No live manuscript edits, Overleaf push, new environment, downloaded dataset or bulk archive. Local-only files need a separately chosen backup; no disk-saving claim.']
(R/'REPORT.md').write_text('\n'.join(lines)+'\n')
paragraph=f"We tested the reviewed compact whole-client deletion path at T=0 on the original Adult, Bank and Credit partitions (k=10; five seeds). Six metadata-only selection roles—size minimum/median/maximum, group-0 fraction minimum/maximum, and minimum smaller surviving group—deduplicated to two clients per dataset, yielding 30 unique cases. All fresh, direct and compact outputs matched the indexed model and declared compact state, including all 270 timed witnesses. Under the resident-data equal-model-output request boundary, the ratios of total fresh to compact times were {s['datasets'][0]['fresh_fast_total_ratio']:.2f}×, {s['datasets'][1]['fresh_fast_total_ratio']:.2f}× and {s['datasets'][2]['fresh_fast_total_ratio']:.2f}×, respectively ({a['fresh_fast_total_ratio']:.2f}× pooled); paired case ratios ranged from {a['fresh_fast_paired_min']:.2f}× to {a['fresh_fast_paired_max']:.2f}×. Compact was {a['direct_fast_total_ratio']:.2f}× faster than direct in pooled request time. Both selected identities retained 1,980 anchors on Adult/Credit and 380 on Bank, so within-dataset variation did not change compact workload size. These overlapping selections, seeds and timing repeats are not independent populations. The result supports speedup across this bounded grid, with setup, cold loading and durable state persistence excluded; it establishes neither a general 10× guarantee nor adequacy relative to unmeasured refinement."
(R/'APPENDIX_PARAGRAPH.md').write_text(paragraph+'\n')
(R/'INTEGRATION_NOTES.md').write_text('# Integration notes — proposal only\n\n'+paragraph+'\n\nUse APPENDIX_PARAGRAPH.md as optional robustness text, with tables/selection.csv and tables/summary.csv (dimension=client) or figures/client_latency.png. Keep the detailed API timing and cache/persistence contract in the appendix/report. Do not replace the T15/P2/P3 learner or timing claims with this T0 experiment. Do not describe 90 independent cases: actual count is 30, representing six dataset/client requests, five seeds each; six roles overlap. Role summaries must not be pooled a second time.\n\nPhi is the maximum of group-average costs; G is their sum. No T1/T2 reference was run or imported here. Any future comparison across budgets is a quality/compute reference, not an exact-unlearning speed ratio. Preserve the fixed-preprocessing, trusted-state, persistent-ID and model-output-only limits. Existing source review proves a conditional invariant; present checks are additional finite evidence. No new novelty claim over Pan whole-client deletion or Ghadiri multi-group treatment is proposed. No manuscript or Overleaf content was changed.\n')
# Static chart: five-seed case means, retaining all seed dots.
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig,axes=plt.subplots(1,2,figsize=(11,4.7),layout='constrained');colors={'fresh':'#6c7785','direct':'#d68a25','fast':'#167f83'}
labels=[x['group'] for x in s['clients']]
for mi,m in enumerate(('fresh','direct','fast')):
 xs=[];ys=[]
 for i,label in enumerate(labels):
  ds,cl=label.split('/c');rr=[r for r in cases if r['dataset']==ds and r['client']==cl]
  xs.extend([i+(mi-1)*.23]*len(rr));ys.extend(float(r[f'{m}_request_e2e_seconds_mean_ms']) for r in rr)
 axes[0].scatter(xs,ys,s=19,color=colors[m],alpha=.7,label={'fresh':'Fresh T0','direct':'Direct T0','fast':'Compact T0'}[m])
axes[0].set_yscale('log');axes[0].set_ylabel('Request latency (ms; log scale)');axes[0].set_xticks(range(6),labels,rotation=35,ha='right');axes[0].legend(frameon=False);axes[0].set_title('Every seed mean, three timed repeats')
for i,label in enumerate(labels):
 ds,cl=label.split('/c');v=[float(r['fresh_fast_ratio']) for r in cases if r['dataset']==ds and r['client']==cl];axes[1].scatter([i]*len(v),v,color=colors['fast'],s=24)
axes[1].axhline(10,color='#888888',linestyle=':',linewidth=1,label='10× reference');axes[1].set_xticks(range(6),labels,rotation=35,ha='right');axes[1].set_ylabel('Paired Fresh / Compact request ratio');axes[1].set_title('30 cases; six actual client requests');axes[1].legend(frameon=False)
for ax in axes:ax.spines[['top','right']].set_visible(False);ax.grid(axis='y',alpha=.15)
fig.suptitle('Whole-client T0 identity robustness',fontsize=15);fig.savefig(R/'figures/client_latency.png',dpi=170);plt.close(fig)
